(function(){'use strict';var doc=document.documentElement;var reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;var navbar=document.getElementById('navbar');function onScrollNav(){navbar.classList.toggle('scrolled',window.scrollY>50);}
onScrollNav();window.addEventListener('scroll',onScrollNav,{passive:true});var themeToggle=document.getElementById('theme-toggle');function applyTheme(theme){doc.dataset.theme=theme;var isDark=theme==='dark';themeToggle.setAttribute('aria-pressed',String(isDark));themeToggle.setAttribute('aria-label',isDark?'切换浅色模式':'切换深色模式');}
applyTheme(doc.dataset.theme==='dark'?'dark':'light');themeToggle.addEventListener('click',function(){var next=doc.dataset.theme==='dark'?'light':'dark';applyTheme(next);try{localStorage.setItem('theme',next);}catch(e){}});var menuBtn=document.getElementById('mobile-menu');var navMenu=document.getElementById('nav-menu');function setMenu(open){navMenu.classList.toggle('open',open);menuBtn.setAttribute('aria-expanded',String(open));menuBtn.setAttribute('aria-label',open?'关闭菜单':'打开菜单');}
menuBtn.addEventListener('click',function(){setMenu(menuBtn.getAttribute('aria-expanded')!=='true');});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&navMenu.classList.contains('open')){setMenu(false);menuBtn.focus();}});document.addEventListener('click',function(e){if(navMenu.classList.contains('open')&&!navMenu.contains(e.target)&&!menuBtn.contains(e.target)){setMenu(false);}});document.querySelectorAll('a[href^="#"]').forEach(function(anchor){anchor.addEventListener('click',function(e){var id=anchor.getAttribute('href');if(id.length<2){return;}
var target=document.querySelector(id);if(!target){return;}
e.preventDefault();target.scrollIntoView({behavior:reduceMotion?'auto':'smooth',block:'start'});if(navMenu.classList.contains('open')){setMenu(false);}
target.setAttribute('tabindex','-1');target.focus({preventScroll:true});});});var navLinks=Array.prototype.slice.call(document.querySelectorAll('.nav-link'));var sections=navLinks.map(function(link){return document.querySelector(link.getAttribute('href'));}).filter(Boolean);function setActiveLink(id){navLinks.forEach(function(link){var active=link.getAttribute('href')==='#'+id;link.classList.toggle('active',active);if(active){link.setAttribute('aria-current','true');}
else{link.removeAttribute('aria-current');}});}
if('IntersectionObserver'in window&&sections.length){var spy=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){setActiveLink(entry.target.id);}});},{rootMargin:'-40% 0px -55% 0px'});sections.forEach(function(s){spy.observe(s);});}
var backToTop=document.getElementById('back-to-top');function onScrollTop(){backToTop.classList.toggle('visible',window.scrollY>600);}
onScrollTop();window.addEventListener('scroll',onScrollTop,{passive:true});backToTop.addEventListener('click',function(){window.scrollTo({top:0,behavior:reduceMotion?'auto':'smooth'});});var revealEls=document.querySelectorAll('.work-card, .about-card');if(!reduceMotion&&'IntersectionObserver'in window){revealEls.forEach(function(el,i){el.classList.add('reveal');el.style.transitionDelay=(i%3)*60+'ms';});var io=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('revealed');io.unobserve(entry.target);}});},{threshold:0.1});revealEls.forEach(function(el){io.observe(el);});}
var yearEl=document.getElementById('year');if(yearEl){yearEl.textContent=String(new Date().getFullYear());}})();